// 🤖 Generated by DevOps QA Agent — review before relying on this test.
//
// WAY 15 smoke profile for the checkout read path. Read-only by default:
// GET/HEAD only, no writes, so it is safe to point at shared staging.
// Never run against PROD_URL — load-test-writer refuses that.
//
// Run:
//   API_BASE_URL=https://staging.shop.example.com \
//   API_TEST_TOKEN=$API_TEST_TOKEN \
//   API_PERF_THRESHOLD_MS=2000 \
//   k6 run --summary-export=./smoke-summary.json smoke.js
//
// Exit code 99 means a threshold was crossed. That is a finding, not a tool error.

import http from 'k6/http';
import { check, sleep, expectedStatuses } from 'k6';

const BASE = __ENV.API_BASE_URL;
const HEADERS = {
  Authorization: `Bearer ${__ENV.API_TEST_TOKEN}`,
  'Content-Type': 'application/json',
};
const P95 = Number(__ENV.API_PERF_THRESHOLD_MS || 2000);

// Path params come from a small fixture list rather than random IDs: a random
// code measures 404 latency, not the endpoint.
const DISCOUNT_CODES = ['SUMMER24', 'WELCOME10', 'EXPIRED99'];

export const options = {
  // smoke: 1-2 VUs, 30s - proves the script works and gives baseline latency
  stages: [
    { duration: '10s', target: 2 },
    { duration: '20s', target: 2 },
  ],
  // EXPIRED99 answers 410 by design. Without this, that correct response would
  // be counted as a failed request and trip http_req_failed.
  responseCallback: expectedStatuses(200, 410),
  thresholds: {
    http_req_failed: ['rate<0.01'],
    http_req_duration: [`p(95)<${P95}`],
    'http_req_duration{endpoint:GET /v1/cart}': [`p(95)<${P95}`],
    'http_req_duration{endpoint:GET /v1/discounts/{code}}': [`p(95)<${P95}`],
    'http_req_duration{endpoint:GET /v1/orders}': [`p(95)<${P95}`],
  },
};

export default function () {
  const cart = http.get(`${BASE}/v1/cart`, {
    headers: HEADERS,
    tags: { endpoint: 'GET /v1/cart' },
  });
  check(cart, { 'cart status 200': r => r.status === 200 });

  // Pick by iteration counter, not Math.random(), so a failing iteration can be
  // reproduced by number.
  const code = DISCOUNT_CODES[__ITER % DISCOUNT_CODES.length];
  const discount = http.get(`${BASE}/v1/discounts/${code}`, {
    headers: HEADERS,
    // Tag with the path template, not the resolved URL, so results group per endpoint
    tags: { endpoint: 'GET /v1/discounts/{code}' },
  });
  // EXPIRED99 is expected to answer 410, which is a correct response, not a fault
  check(discount, { 'discount status 200 or 410': r => r.status === 200 || r.status === 410 });

  const orders = http.get(`${BASE}/v1/orders`, {
    headers: HEADERS,
    tags: { endpoint: 'GET /v1/orders' },
  });
  check(orders, { 'orders status 200': r => r.status === 200 });

  sleep(1); // think time - never hammer without pauses unless the profile is stress/spike
}
